sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var messStaffUseCases = [
        'Food Quality Complaint',
        'Meal Not Available',
        'Meal Reservation / Pre-Booking',
        'Emergency Food Assistance',
        'Missed Meal Request',
		'Food Hygiene Issue'
    ];

    var adminUseCases = [
        'Special Diet Request',
        'Smart Menu Recommendation',
        'Food Wastage Reporting',
        'Allergy Management Request',
        'Hostel Mess Billing Issue',
        'Food Menu Feedback'
    ];

    var useCase = current.getDisplayValue('use_case');

    if (messStaffUseCases.indexOf(useCase) !== -1) {

        var messGroup = new GlideRecord('sys_user_group');
        messGroup.addQuery('name', 'Mess Staff');
        messGroup.setLimit(1);
        messGroup.query();

        if (messGroup.next()) {
            current.assignment_group = messGroup.getUniqueValue();
        }

    } else if (adminUseCases.indexOf(useCase) !== -1) {

        var adminGroup = new GlideRecord('sys_user_group');
        adminGroup.addQuery('name', 'Admin Staff');
        adminGroup.setLimit(1);
        adminGroup.query();

        if (adminGroup.next()) {
            current.assignment_group = adminGroup.getUniqueValue();
        }
    }

})(current, previous);
